28|     DynArr d;
29|     init(d);
30|     int x;
31|     while (cin >> x) push(d, x);
32|     cout << d.size << "\n";
33|     for (int i = d.size - 1; i >= 0; i--) cout << d.data[i] << " ";
34|     cout << "\n";
35|     delete[] d.data;
36|     return 0;
37| }
